import { useEffect, useState } from "react";

type Item = { id: string; price: number };

export function Cart({ initialItems }: { initialItems: Item[] }) {
  const [items, setItems] = useState(initialItems);
  const [total, setTotal] = useState(0);

  // Derived data copied into state: an extra render, briefly stale
  useEffect(() => {
    setTotal(items.reduce((sum, item) => sum + item.price, 0));
  }, [items]);

  // Sees "items changed", not what the user did
  useEffect(() => {
    if (items.length > 0) showToast("Added to cart");
  }, [items]);
  function add(item: Item) {
    setItems([...items, item]);
  }
  function remove(id: string) {
    setItems(items.filter((item) => item.id !== id));
  }
  return <CartView items={items} total={total} onAdd={add} onRemove={remove} />;
}

import { useState } from "react";

type Item = { id: string; price: number };

export function Cart({ initialItems }: { initialItems: Item[] }) {
  const [items, setItems] = useState(initialItems);
  // Calculated during render: always matches items, no extra pass
  const total = items.reduce((sum, item) => sum + item.price, 0);

  function add(item: Item) {
    setItems([...items, item]);
    showToast("Added to cart"); // caused by this click, so it lives here
  }
  function remove(id: string) {
    setItems(items.filter((item) => item.id !== id));
  }
  return <CartView items={items} total={total} onAdd={add} onRemove={remove} />;
}
